theorem record_chronology (c : ℝ) (N : ℕ) (hN : 1 ≤ N)
    (hne : ∃ d : ℕ → ℕ, (∀ i < N, 1 ≤ d i) ∧ Confined c d N) :
    rmin c N = sInf {m : ℕ | Odd m ∧ Confined c (fun i => a (orbit m i)) N}

theorem barrierConfined_of_chord {K : ℕ → ℕ}
    (hchord : ∀ j ≤ N, ∀ p : ℕ, N * p ≤ j * K N → p ≤ K j)
    {w : FiniteValuationWord N} (hw : w.total ≤ K N) {r : ℕ}
    (hr : ∀ j ≤ N, N * (w.rotate r).prefixSum j ≤ j * w.total) :
    BarrierConfined K (w.rotate r)

theorem three_mul_coprimeSixRank_le_add_two {x : ℕ}
    (hodd : Odd x) (hthree : ¬ 3 ∣ x) :
    3 * coprimeSixRank x ≤ x + 2

theorem IsProbabilityLaw.event_eq_tsum_singletons {α : Type*} {P : EventProb α}
    (hP : IsProbabilityLaw P) (E : Set α) :
    P E = ∑' x, Set.indicator E (fun y => P {y}) x

theorem IsProbabilityLaw.ext_singleton {α : Type*} {P Q : EventProb α}
    (hP : IsProbabilityLaw P) (hQ : IsProbabilityLaw Q)
    (h_singleton : ∀ x, P {x} = Q {x}) : P = Q

theorem confined_predecessor {y : ℕ} (hy : Odd y) (h3 : y % 3 = 2) {c : ℝ} (hc : 0 ≤ c) {N : ℕ}
    (hconf : Confined c (orbitWord y) N) :
    Confined c (orbitWord ((2 * y - 1) / 3)) (N + 1)

theorem swapWeight_le_of_cos_le (ψ : ℕ → ℝ) {c : ℝ}
    (hc : ∀ d ∈ lo A u, |Real.cos (π * (ψ d - ψ (u - d)))| ≤ c) :
    swapWeight A u ψ ≤ 2 * c * (lo A u).card + (single A u).card

theorem betaP_eq_iff (t : ℕ) (hj1 : 1 ≤ j0) {P Q : FiniteValuationWord j0}
    (hP : P ∈ shellP b j0 σ) (hQ : Q ∈ shellP b j0 σ) :
    betaP t P = betaP t Q ↔ topB j0 σ t P = topB j0 σ t Q

theorem yPrime_mod (t : ℕ) (hj1 : 1 ≤ j0) {P : FiniteValuationWord j0}
    (hP : P ∈ shellP b j0 σ) :
    yPrime j0 σ t P % 2 ^ (σ + 1) = leastRealizer P.toInfinite j0

theorem norm_sum_piFinset_eq_prod {R : ℕ} {κ : Fin R → Type*}
    (B : ∀ r, Finset (κ r)) (θ : ∀ r, κ r → ℝ) :
    ‖∑ f ∈ Fintype.piFinset B, ee (∑ r, θ r (f r))‖ = ∏ r, ‖∑ x ∈ B r, ee (θ r x)‖

theorem kernel_le_of_grid (H : ℕ) (a : ℝ) {q : ℕ} (hq : 1 ≤ q) (n : ℤ) {d : ℝ}
    (hd : |d| ≤ 1 / (2 * q)) {c : ℕ} (hc : (c : ℤ) = n % q) (hc0 : c ≠ 0) :
    ‖∑ k ∈ range H, ee ((a + k) * ((n : ℝ) / q + d))‖ ≤ q / c + q / (q - c)

theorem white_step (hrec : ∀ j, (2 : ℤ) ^ M (j + 1) ∣ 27 * e (j + 1) - e j)
    (hcen : ∀ j, 2 * |e j| ≤ 2 ^ M j) (hM : ∀ j, M (j + 1) ≤ M j) {j : ℕ}
    (hw : white e M j) (hw' : white e M (j + 1)) : (27 : ℤ) ∣ e j ∧ e (j + 1) * 27 = e j

theorem sum_union_le_of_nonneg {ι : Type*} [DecidableEq ι] {A B : Finset ι}
    {F : ι → ℝ} (hF : ∀ x ∈ A ∪ B, 0 ≤ F x) :
    ∑ x ∈ A ∪ B, F x ≤ ∑ x ∈ A, F x + ∑ x ∈ B, F x

theorem maxTriangleLE_box {η : ℝ} (hη : 0 < η) (h : SublinearMaxTriangle η) {c ε : ℝ}
    (hc : 0 ≤ c) (hε : 0 < ε) :
    ∃ L₀ : ℝ, ∀ m L : ℕ, L₀ ≤ L → (m : ℝ) ≤ c * L → MaxTriangleLE η (box m L) (ε * L)

theorem distZ_phase_ge_of_white {m i x : ℕ} (hx : x ≤ m) {η : ℝ}
    (hwhite : ¬ black (m - x) (i + 1) η) :
    η - 2 ^ x / (2 ^ m * 3 ^ (i + 1)) ≤ distZ (pairPhase 1 m i x - pairPhase 1 m i (x + 1))

theorem card_pairB_le_two_mul_elig {j0 : ℕ} {c : Fin (j0 + 1) → ℕ} {r : ℕ}
    (hne : (Elig b c r).Nonempty) :
    (BlockCubeInstance.pairB b c r).card ≤ 2 * (Elig b c r).card

theorem goodPair_of_shape_not_bad {m N0 : ℕ} {d : ℝ} {lam j0 : ℕ} {c : Fin (j0 + 1) → ℕ} {r : ℕ}
    (hs : ShapeGood b N0 c r) (hnb : ¬ BadPair b m N0 d lam c r) :
    GoodPair b m N0 d lam c r

theorem val_le_of_window_rem {w : ℕ → σ → σ → ℝ} (hw : ∀ l x y, 0 ≤ w l x y) {K W ρ : ℕ}
    {M Mrem : ℝ}
    (hM : ∀ l y, val w l K y ≤ M) (hMrem : ∀ y, val w (W * K) ρ y ≤ Mrem)
    (hMrem0 : 0 ≤ Mrem) (x : σ) : val w 0 (W * K + ρ) x ≤ M ^ W * Mrem

theorem card_big_mul_le {j0 σ N0 : ℕ} (hj : 1 ≤ j0) {P : FiniteValuationWord j0}
    (hP : P ∈ shellP b j0 σ) :
    ((range (j0 / 2)).filter (Big b N0 (pairκ j0 P))).card * (N0 + 2) ≤ σ

theorem card_pairB_add_le_diff {j0 : ℕ} {P : FiniteValuationWord j0} (hpos : P.Positive) {r : ℕ}
    (h : 2 * r + 2 ≤ j0) :
    (pairB b (pairκ j0 P) r).card + 1 ≤ P.prefixSum (2 * r + 2) - P.prefixSum (2 * r)

theorem sum_card_pairB_add_le {j0 σ : ℕ} (hj : 1 ≤ j0) {P : FiniteValuationWord j0}
    (hP : P ∈ shellP b j0 σ) :
    ∑ r ∈ range (j0 / 2), ((pairB b (pairκ j0 P) r).card + 1) ≤ σ

theorem cget_pairκ_le {j0 σ : ℕ} (hj : 1 ≤ j0) {P : FiniteValuationWord j0}
    (hP : P ∈ shellP b j0 σ) {r : ℕ} (hr : 2 * r ≤ j0) :
    cget (pairκ j0 P) (2 * r) = P.prefixSum (2 * r) ∧ P.prefixSum (2 * r) ≤ σ

theorem nodd_companion (b : ℕ → ℕ) {m : ℕ} {d : ℝ} {lam : ℕ} (hl : lam ≤ 2 ^ m) {j : ℕ}
    (P : FiniteValuationWord j) :
    OddBlack.Nodd b m d (2 ^ m - lam) P = OddBlack.Nodd b m d lam P

theorem descent_of_L1_lt_thirteen_ninths {M0 : ℕ}
    (h : ∀ M : ℕ, M0 ≤ M → 0 < M → Odd M → ¬ Confined 1 (orbWord M) (13 * M / 9)) :
    ∀ M : ℕ, M0 ≤ M → 0 < M → Odd M → ∃ n, 1 ≤ n ∧ orbit M n < M

theorem descent_of_L1_lt_two_mul {M0 : ℕ}
    (h : ∀ M : ℕ, M0 ≤ M → 0 < M → Odd M → ¬ Confined 1 (orbWord M) (2 * M)) :
    ∀ M : ℕ, M0 ≤ M → 0 < M → Odd M → ∃ n, 1 ≤ n ∧ orbit M n < M

